INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9d8f66c6-133d-4aa8-9586-001bfbc492c9', 'うっかりかみのけをみじかく切りすぎちゃったけど、そのあといぜんよりもよくナンパされるようになった。', 'Meskipun aku tidak sengaja memotong rambutku lebih pendek dari yang kuinginkan, sejak itu semakin banyak orang yang menggodaku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('aee5d7f5-f9cc-42da-a970-e1bed90c9685', 'vocabulary', '少し', '少し', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kata ini berupa kanji tunggal dengan hiragana di dalamnya, meskipun tidak ada petunjuk spesifik mengenai jenis kata tersebut. Artinya, biasanya Anda dapat menebaknya apakah itu kata benda, kata keterangan, atau kata sifat na (dalam hal ini kata benda/kata keterangan). Arti kata ini hampir sama dengan kanji, namun membuatnya cukup mudah. Arti kanji untuk 少 sedikit, dan arti bentuk vocabnya sedikit atau sedikit.', 'Kata ini berupa kanji tunggal dengan hiragana di dalamnya, meskipun tidak ada petunjuk spesifik mengenai jenis kata tersebut. Artinya, biasanya Anda dapat menebaknya apakah itu kata benda, kata keterangan, atau kata sifat na (dalam hal ini kata benda/kata keterangan). Arti kata ini hampir sama dengan kanji, namun membuatnya cukup mudah. Arti kanji untuk 少 sedikit, dan arti bentuk vocabnya sedikit atau sedikit.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
