INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6dbd3c77-8d1f-4d87-9851-6446cf3ff071', 'vocabulary', '十台', '十台', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Jika Anda mengetahui kedua kanji tersebut secara terpisah, Anda harus bisa menggabungkan keduanya sehingga membentuk arti dari kanji tersebut.', 'Jika Anda mengetahui kedua kanji tersebut secara terpisah, Anda harus bisa menggabungkan keduanya sehingga membentuk arti dari kanji tersebut.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
