INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('81ce5883-9433-4f03-b8ee-1ecc23cf4896', '今、公用でパリにきています。', 'Saya datang ke Paris sekarang untuk urusan resmi.') ON CONFLICT DO NOTHING;
