INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4290cfdb-35ca-44f5-b1c1-47f98b0d600c', 'vocabulary', '休止', '休止', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Perhentian yang sekedar istirahat (alias tidak permanen) bukanlah perhentian langsung. Anda berencana untuk melanjutkan lagi. Itu sebabnya ini adalah jeda.', 'Perhentian yang sekedar istirahat (alias tidak permanen) bukanlah perhentian langsung. Anda berencana untuk melanjutkan lagi. Itu sebabnya ini adalah jeda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
