INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4290cfdb-35ca-44f5-b1c1-47f98b0d600c', 'パソコンのスリープと休止じょうたいのちがいをおしえてください。', 'Bisakah Anda memberi tahu saya perbedaan antara mode tidur dan mode hibernasi di komputer?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4290cfdb-35ca-44f5-b1c1-47f98b0d600c', 'しごとのと中で、小まめに小休止をとってエクササイズをするようにしています。', 'Saya mencoba untuk beristirahat sejenak dan sering berolahraga selama bekerja.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e95d8bb4-a9b7-4271-b2a6-0115d26b67f9', 'vocabulary', '少年', '少年', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Seseorang yang berumur beberapa tahun adalah seseorang yang masih muda. Tapi, dulu orang Jepang dan Cina cenderung menyukai laki-laki, jadi yang ini berarti laki-laki, biasanya laki-laki. Maaf gadis-gadis! Gunakan kekesalan Anda pada kanji ini untuk mengingatnya dengan lebih baik.', 'Seseorang yang berumur beberapa tahun adalah seseorang yang masih muda. Tapi, dulu orang Jepang dan Cina cenderung menyukai laki-laki, jadi yang ini berarti laki-laki, biasanya laki-laki. Maaf gadis-gadis! Gunakan kekesalan Anda pada kanji ini untuk mengingatnya dengan lebih baik.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
