INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e95d8bb4-a9b7-4271-b2a6-0115d26b67f9', 'けいさつかんは、一ぱんてきに、少年はんざいのかがいしゃを、けいさつの少年かにれんこうします。', 'Petugas polisi umumnya membawa pelanggar muda ke divisi remaja departemen kepolisian.') ON CONFLICT DO NOTHING;
