INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a9758f22-c611-44d8-b65b-ac39327eab3c', 'vocabulary', '元気', '元気', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Apa asal usul energi Anda? Ini adalah kesehatan Anda. Kata ini juga berarti energi, dan bila digunakan sebagai kata sifat berarti sehat atau energik.', 'Apa asal usul energi Anda? Ini adalah kesehatan Anda. Kata ini juga berarti energi, dan bila digunakan sebagai kata sifat berarti sehat atau energik.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
