INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ad058e9e-ef5e-432a-a39d-8fdfbcc4fa52', 'かれは、日けいアメリカ人二世の一人です。', 'Dia salah satu generasi kedua orang Jepang-Amerika.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ad058e9e-ef5e-432a-a39d-8fdfbcc4fa52', 'せいこうしている二世タレントは少ない。', 'Tidak banyak anak selebritis yang bisa menjadi selebriti juga.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ad058e9e-ef5e-432a-a39d-8fdfbcc4fa52', '私は、父が日系イギリス人二世だということを知らなかった。', 'Saya tidak tahu kalau ayah saya adalah generasi kedua Jepang-Inggris.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b04b2634-2971-4666-9f39-9393010e5244', 'vocabulary', '三世', '三世', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Generasi ketiga adalah generasi ketiga. Tergantung pada konteksnya, terkadang Anda dapat menggunakan kata ini untuk mengatakan bahwa Anda adalah generasi ketiga Jepang. Namun biasanya, Anda ingin menentukan apakah Anda generasi ketiga Jepang atau berkewarganegaraan lain.', 'Generasi ketiga adalah generasi ketiga. Tergantung pada konteksnya, terkadang Anda dapat menggunakan kata ini untuk mengatakan bahwa Anda adalah generasi ketiga Jepang. Namun biasanya, Anda ingin menentukan apakah Anda generasi ketiga Jepang atau berkewarganegaraan lain.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b04b2634-2971-4666-9f39-9393010e5244', 'Generasi Ketiga', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b04b2634-2971-4666-9f39-9393010e5244', 'さんせい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b04b2634-2971-4666-9f39-9393010e5244', 'このスクールには三世の子がたくさんいます。', 'Ada banyak anak generasi ketiga di sekolah ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b04b2634-2971-4666-9f39-9393010e5244', '三世のほとんどはシアトル市生まれです。', 'Kebanyakan orang generasi ketiga lahir di Seattle.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b04b2634-2971-4666-9f39-9393010e5244', 'これは、三世のアイデンティティーについての本です。', 'Buku ini tentang identitas generasi ketiga.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cd887337-06d0-42fe-93f2-8b5ddc013034', 'vocabulary', '主に', '主に', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', '主 artinya utama, jadi jika ditambahkan に, ia menjadi kata keterangan terutama.', '主 artinya utama, jadi jika ditambahkan に, ia menjadi kata keterangan terutama.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
