INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cd887337-06d0-42fe-93f2-8b5ddc013034', '主に日本ごをべんきょうしています。', 'Saya terutama belajar bahasa Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cd887337-06d0-42fe-93f2-8b5ddc013034', 'ポートランドでは、赤い車と白い車が主にうれています。', 'Terutama mobil merah dan putih yang dijual di Portland.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cd887337-06d0-42fe-93f2-8b5ddc013034', '彼は研究者で、主にバナナに興味があります。', 'Beliau adalah seorang peneliti yang minat utamanya adalah pada pisang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c3b7afb6-5602-4014-946d-80fab9ec1535', 'vocabulary', '主人', '主人', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Orang yang ahli bukan hanya seorang ahli. Anda harus mengingat kembali saat mereka membuat kanji ini. Siapa masternya? Itu adalah kepala rumah tangga. Kepala rumah tangga ini mungkin menyuruh pelayannya apa yang harus dilakukan dan dia suka memerintah dan sebagainya. Dia adalah orang yang ahli. 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c3b7afb6-5602-4014-946d-80fab9ec1535', 'Kepala Rumah Tangga', true) ON CONFLICT DO NOTHING;
