INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c3b7afb6-5602-4014-946d-80fab9ec1535', 'きのう、ご主人とどこかへいきましたか？', 'Apakah Anda dan suami pergi ke suatu tempat kemarin?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c3b7afb6-5602-4014-946d-80fab9ec1535', 'ご主人さま、それは少しかいすぎではないでしょうか。', 'Saya khawatir Anda membeli terlalu banyak, tuan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c3b7afb6-5602-4014-946d-80fab9ec1535', '私の主人は何の信念も無い政治家なんです。', 'Suami saya adalah seorang politisi yang tidak memiliki keyakinan apa pun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a172593d-4371-4597-9c38-b7a18d42d85d', 'vocabulary', '仕方', '仕方', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Cara melakukan pada dasarnya adalah “cara melakukan” sesuatu. Sederhananya, inilah caranya. "Apa caramu melakukan ini?" Tidak tidak tidak. “Apa METODEmu.” Ini dia.', 'Cara melakukan pada dasarnya adalah “cara melakukan” sesuatu. Sederhananya, inilah caranya. "Apa caramu melakukan ini?" Tidak tidak tidak. “Apa METODEmu.” Ini dia.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
