INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a172593d-4371-4597-9c38-b7a18d42d85d', 'しかた', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a172593d-4371-4597-9c38-b7a18d42d85d', 'おじぎの仕方をおしえてください。', 'Tolong ajari saya cara membungkuk.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a172593d-4371-4597-9c38-b7a18d42d85d', 'フランス人の友人にフランスしきのあいさつの仕方をおしえてもらいました。', 'Teman Prancis saya mengajari saya cara menyapa orang dengan cara Prancis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a172593d-4371-4597-9c38-b7a18d42d85d', '「運転の仕方」という本は今年のベストセラーとなった。', '"How to Drive" menjadi buku terlaris tahun ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('81a96bdc-be03-478f-8ec5-6ee9accaa5ae', 'vocabulary', '仕方がない', '仕方がない', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Bagian kanji dari kata ini seperti mengatakan "the doing way" alias cara melakukan sesuatu. Jadi, ketika Anda tidak punya cara untuk melakukan sesuatu, tidak ada yang bisa Anda lakukan. Maka lahirlah ungkapan populer Jepang: 仕方がない, yang artinya mau bagaimana lagi, tidak ada gunanya, atau tidak ada jalan lain. Ini adalah ungkapan yang sangat bagus untuk mengetahui apakah Anda berada di Jepang.', 'Bagian kanji dari kata ini seperti mengatakan "the doing way" alias cara melakukan sesuatu. Jadi, ketika Anda tidak punya cara untuk melakukan sesuatu, tidak ada yang bisa Anda lakukan. Maka lahirlah ungkapan populer Jepang: 仕方がない, yang artinya mau bagaimana lagi, tidak ada gunanya, atau tidak ada jalan lain. Ini adalah ungkapan yang sangat bagus untuk mengetahui apakah Anda berada di Jepang.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('81a96bdc-be03-478f-8ec5-6ee9accaa5ae', 'Mau bagaimana lagi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('81a96bdc-be03-478f-8ec5-6ee9accaa5ae', 'It''s No Use', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('81a96bdc-be03-478f-8ec5-6ee9accaa5ae', 'There''s No Other Way', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('81a96bdc-be03-478f-8ec5-6ee9accaa5ae', 'しかたがない', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('81a96bdc-be03-478f-8ec5-6ee9accaa5ae', 'かれがおこるのは、仕方がないよ。', 'Kalau dia marah, mau bagaimana lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('81a96bdc-be03-478f-8ec5-6ee9accaa5ae', '泣いてばかりいても仕方がないよ。', 'Tidak ada gunanya hanya menangis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('81a96bdc-be03-478f-8ec5-6ee9accaa5ae', 'お前は本当に仕方がないやつだ！', 'Anda benar-benar putus asa!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3b197695-d71d-4cfd-b4ef-fd8eab5493e0', 'vocabulary', '代わる', '代わる', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya pengganti, jadi arti kata ini bisa kita pahami melalui itu: Mengganti / menggantikan.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya pengganti, jadi arti kata ini bisa kita pahami melalui itu: Mengganti / menggantikan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
