INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a8e46ef1-886a-4536-b007-232680859d7e', 'かれは、一代でここまでかいしゃを大きくした。', 'Dia menjadikan perusahaan ini jauh lebih besar hanya dalam satu generasi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a8e46ef1-886a-4536-b007-232680859d7e', 'コウイチは一世一代の大しょうぶに打って出た。', 'Koichi pergi untuk bertaruh sekali seumur hidup.') ON CONFLICT DO NOTHING;
