INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('838faea9-7545-4b76-8896-fceaa4c5b42b', '日本語は、主語ー目的語ー動詞の言語ですが、英語は主語ー動詞ー目的語の言語です。', 'Bahasa Jepang adalah bahasa subjek-objek-kata kerja sedangkan bahasa Inggris adalah bahasa subjek-kata kerja-objek.') ON CONFLICT DO NOTHING;
