INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('14b06b15-1e68-4cd2-b6ec-9fe0795dfb38', 'vocabulary', '人口', '人口', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Jumlah orang yang mempunyai mulut (yang harus Anda beri makan) adalah populasi yang harus Anda beri makan.', 'Jumlah orang yang mempunyai mulut (yang harus Anda beri makan) adalah populasi yang harus Anda beri makan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
