INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('14b06b15-1e68-4cd2-b6ec-9fe0795dfb38', '人口のはんぶんはだんせいです。', 'Separuh penduduknya adalah laki-laki.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('14b06b15-1e68-4cd2-b6ec-9fe0795dfb38', 'このむらの人口はたったの二十三にんです。', 'Penduduk desa ini hanya 23 orang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('14b06b15-1e68-4cd2-b6ec-9fe0795dfb38', 'じぶんのまちの人口をしらないにほんじんはおおい。', 'Banyak orang Jepang yang tidak mengetahui jumlah penduduk di kotanya sendiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5391c288-647d-4686-af3b-5dd3de50ae67', 'vocabulary', '子牛', '子牛', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Anda mempunyai anak sapi. Menurutmu anak sapi itu apa? Mungkin anak sapi atau bayi sapi.', 'Anda mempunyai anak sapi. Menurutmu anak sapi itu apa? Mungkin anak sapi atau bayi sapi.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
